INSERT INTO glossary (term, type, description, first_chapter, aliases) VALUES
('Brine Court', 'concept', 'A coastal royal house with a long shoreline tradition of caravan-defence operations. Among the first foreign powers to write Beambreak after the road expansion, sending a brief, formal letter drafted in the tone of polite curiosity that conceals nothing of the urgency underneath. Their experience and twenty thousand riders make them a key partner in any expanded military arrangement.', 61, ARRAY[]::text[]),
('Iri''kai', 'creature', 'The human term for the Vahar''ai people. A long-lived winged species with a proud tradition the humans have mischaracterised as caravan-raiding. Their letter to Beambreak acknowledged this reputation with the specific Iri''kai flat honesty.', 61, ARRAY['Iri kai']::text[]),
('The Skein', 'concept', 'A reclusive royal house that had not written to Beambreak in a century before sending a formal, carefully phrased, extremely short letter acknowledging the road''s construction. They hold maps of the trans-volcanic country no other power possesses. The break in their century-long silence is treated by Mira as a signal of historic significance.', 61, ARRAY['Skein']::text[]),
('Stoneblood', 'concept', 'A royal house whose refiners are uniquely positioned to provide mineral supplies. Wrote a brief letter to Beambreak offering to commit to delivery schedules in exchange for early standing in the new trade network forming around the road.', 61, ARRAY[]::text[]),
('Hollow People', 'creature', 'The collective name applied to those marked by the Hollowing — survivors and altered descendants of the affliction that swept the Hjord herds and beyond. The expedition to the volcanic ridge included a Hollow woman reported to shape stone at inhuman speed.', 61, ARRAY[]::text[]),
('Lady Genau', 'character', 'Errol Genau''s sister, who holds one of the three keys to the Genau Seat''s inner archives. Errol secured her dependence over forty years through a combination of social isolation and carefully curated access to her own children. She is one of three controlled trust-holders inside her own household.', 61, ARRAY[]::text[]),
('Train', 'concept', 'Vehn''s transit invention, conceived after Aldwyn described the principle. The system runs on continuous stone plinths with grooves of precise width, drainage channels beneath, and stations placed at standard intervals so people know where to wait. Stations are styled distinctively (round, pointed, wide flat, tall narrow) so passengers can identify their stop without being told.', 61, ARRAY['trains', 'train-track']::text[]),
('The Doctor', 'character', 'The self-given title of the spiderfolk practitioner who performed The First''s modification — the procedure that could have saved the spiderfolk people but which he has refused to perform again. He refused his birth name within the first century of his life and has carried the title since. The practitioner Sam later renames Ossian.', 63, ARRAY['Doctor']::text[]),
('Ossian', 'character', 'The name Sam gives the Doctor — an old name offered as a gift, on the grounds that titles are useful but not names. The Doctor accepts it. Ossian is the spiderfolk practitioner who performed the original modification on The First and who has spent the subsequent century refusing to repeat the procedure that could save his species.', 64, ARRAY[]::text[]),
('Itarrek', 'character', 'An elder Vahar''ai (Iri''kai) who walked twenty-two days from the high uplands to reach Beambreak. One hundred and forty-eight years old and considered middle-aged among his people. Architect-by-experience: he has observed many species'' large-scale projects and offers Vehn unsolicited but precise counsel on how to keep the road from becoming the opposite of what it was meant to be.', 65, ARRAY[]::text[]),
('Vahar''ai', 'creature', 'The Vahar''ai''s own name for themselves — the people humans call Iri''kai. A winged species that lives meaningfully longer than humans and undertakes long walks rather than long flights in older age. The first vowel is short. Itarrek is the first of his kind to walk into Beambreak in living memory.', 65, ARRAY['Vahar ai']::text[]),
('Outer Command', 'concept', 'Beambreak''s military patrol arm responsible for the expanding road. Issues a specific triple-call as the standard approach signal for all patrols. Faces a structural problem: it cannot recruit fast enough to cover the full road at standard intervals, prompting Vehn''s proposal to integrate riders from foreign royal houses for the first time since the Conduit Wars three hundred and twelve years ago.', 65, ARRAY['Beambreak Outer Command']::text[]);